raw=p.read_bytes(); s=raw.decode('utf-8'); nl='\r\n' if '\r\n' in s else '\n'
a=s.index(r'\chapter{دو رهیافت'); b=s.index(r'\part{جعبه ابزار}',a)
t=s[a:b]
assert 'BEGIN GAP RESEARCH EXPANSION' not in t
t=t.replace('یک کران کافیِ رایج (نه لزوماً بهینه) این است', 'یک تخمین مقیاسیِ رایج برای زمان‌بندی خطی، با فرض کنترل مشتق‌های مسیر، چنین است؛ این رابطه به‌تنهایی کران کافیِ عمومی نیست (بخش~\\ref{sec:gap-runtime})')
t=t.replace('از آنجا که $J>0$ و $h_z>0$،','برای ترتیب کامل ترازهای زیر فرض می‌کنیم $0<h_z<J$؛ یکتایی حالت پایه برای هر $J,h_z>0$ برقرار است:')
t=t.replace(r'T\propto\frac{1}{\Delta',r'T_{\mathrm{heuristic}}\propto\frac{1}{\Delta')
t=t.replace('و $T$ مطابق~\\eqref{eq:adiabatic-bound} انتخاب شود','و زمان و خطا با معیارهای بخش~\\ref{sec:gap-runtime} کنترل شوند')
t=t.replace('برای آدیاباتیک: کران‌های دقیق‌تر قضیه؛ زمان‌بندی بهینهٔ غیرخطی؛ عبور از نقطهٔ بحرانی در حد ترمودینامیکی.','برای آدیاباتیک: زمان‌بندی تطبیقی با عدم‌قطعیت گاف؛ آزمون‌های نویزی و تعمیم به سامانهٔ باز؛ عبور از نقطهٔ بحرانی در حد ترمودینامیکی.')
addition="\n% BEGIN GAP RESEARCH EXPANSION\n\\section{گاف انرژی: تعریف دقیق و نقش تقارن}\n\\label{sec:gap-research}\nپژوهش گاف سه مسئلهٔ جدا دارد: یافتن دو تراز درست در یک $s$ ثابت، یافتن کمینه در سراسر مسیر، و تعیین رفتار آن با اندازهٔ سامانه. سپس باید دید این اطلاعات چه زمان‌بندی و چه احتمال موفقیتی را توجیه می‌کند. برای فرمول‌های این بخش $\\hbar$ را صریح می‌نویسیم؛ محاسبات عددی با واحد انرژی $J=1$ و واحد زمان $\\hbar/J$ انجام شده‌اند.\n\n\\subsection{گاف کل، گاف بخش تقارنی و گاف زیر‌فضای هدف}\nبرای پایهٔ یکتا، $\\Delta=E_1-E_0$ تعریف معمول است. اما اگر خوشهٔ $q$ تراز پایین هدف باشد، فاصلهٔ آن از بقیهٔ طیف مهم است:\n\\begin{equation}\n g_{\\mathrm{out}}(s)=E_q(s)-E_{q-1}(s),\\qquad\n P(s)=\\sum_{j=0}^{q-1}|j(s)\\rangle\\langle j(s)|.\n\\end{equation}\nکوچک بودن شکافت درون خوشه لزوماً مانع ماندن در آن نیست. معیار موفقیت\n$P_{\\mathrm{succ}}=\\langle\\Psi(T)|P(1)|\\Psi(T)\\rangle$\nاست، نه وفاداری به یک بردار دلخواه از پایهٔ تبهگن.\n\nاگر تقارن ثابت $S$ در تمام مسیر برقرار باشد، $[H(s),S]=0$، آنگاه\n$[\\partial_sH,S]=0$ نیز برقرار است. حالت اولیه در بخش تقارنی خود باقی می‌ماند.\nعبور ترازهای دو بخش مختلف می‌تواند گاف کل را صفر کند، بی‌آنکه گذار میان آن‌ها مجاز باشد.\nهم گاف کل و هم گاف بخش قابل‌دسترس را گزارش کنید؛ نویزِ شکنندهٔ تقارن این حفاظت را از بین می‌برد.\n\nگاف خنثی در تعداد ذرهٔ ثابت، گاف بار\n$E_0(N+1)+E_0(N-1)-2E_0(N)$، گاف تک‌ذره‌ای و گاف اپتیکی الزاماً یکسان نیستند.\nدر این فصل گاف کم‌انرژیِ هامیلتونی بس‌ذره‌ای در مسیر مشخص بررسی می‌شود؛ نخستین قلهٔ قابل‌اندازه‌گیری ممکن است به‌علت قواعد انتخاب با آن متفاوت باشد.\n\n\\subsection{چرا کوچک‌ترین فاصله به‌تنهایی کافی نیست؟}\nبا مشتق گرفتن از $H|0\\rangle=E_0|0\\rangle$ و ضرب در $\\langle m|$، برای ترازهای غیرتبهگن:\n\\begin{equation}\n \\langle m|\\partial_s0\\rangle\n =\\frac{\\langle m|\\partial_sH|0\\rangle}{E_0-E_m},\\qquad m>0.\n \\label{eq:gap-eigenvector-derivative}\n\\end{equation}\nپس این کمیت‌ها را کنار هم محاسبه می‌کنیم:\n\\begin{equation}\n \\Delta_{m0}=E_m-E_0,\\quad M_{m0}=|\\langle m|\\partial_sH|0\\rangle|,\n \\quad a_m(t)=\\frac{\\hbar|\\dot s|M_{m0}}{\\Delta_{m0}^2}.\n \\label{eq:gap-local-indicator}\n\\end{equation}\n$a_m$ یک شاخص محلیِ بی‌بُعد برای خطر گذار است؛ کوچک بودن آن به‌تنهایی جای قضیهٔ دقیق یا حل دینامیک را نمی‌گیرد. تراز نزدیک با $M_{m0}=0$ از این کانال تحریک نمی‌شود؛ تراز دورتری با عنصر ماتریسی بزرگ ممکن است مهم‌تر باشد.\n\n\\section{از گاف تا زمان: شرط محلی، کران و آزمون دینامیکی}\n\\label{sec:gap-runtime}\n\\subsection{سه معنای متفاوت برای زمان لازم}\nبرآورد شهودی مانند رابطهٔ~\\eqref{eq:adiabatic-bound} برای تخمین مقیاس مفید است.\nکران کافی فرض‌های صریح دربارهٔ همواری، جدایی طیفی و معیار خطا دارد.\nزمان عملی با حل شرودینگر یا آزمایش و آستانهٔ موفقیت تعیین می‌شود. این سه عدد معمولاً یکسان نیستند.\n\nبرای پایهٔ یکتا و مسیر دوبار مشتق‌پذیرِ گاف‌دار، ساختار یک کران از نوع\n\\lr{Jansen--Ruskai--Seiler} برای دامنهٔ نشت، با ثابت عددی $C$ مستقل از $T$:\n\\begin{align}\n \\epsilon_{\\mathrm{amp}}(T)&\\leq \\frac{C\\hbar}{T}\n \\left[\n \\frac{\\|H'(0)\\|}{g(0)^2}+\\frac{\\|H'(1)\\|}{g(1)^2}\\right.\\nonumber\\\\\n &\\left.\\quad+\\int_0^1\\left(\\frac{\\|H''(s)\\|}{g(s)^2}\n +\\frac{\\|H'(s)\\|^2}{g(s)^3}\\right)ds\n \\right].\n \\label{eq:gap-rigorous-structure}\n\\end{align}\nاین نمایش ساختار وابستگی‌هاست، نه نقل ثابت‌های بهینهٔ قضیه؛ $g$ فاصلهٔ حالت هدف از بقیهٔ طیف است. برای زمان‌بندی غیرخطی، مشتق‌ها باید نسبت به $u=t/T$ گرفته شوند. احتمال نشت $\\epsilon_{\\mathrm{amp}}^2$ است؛ خطای دامنه و احتمال را نباید با یک $\\varepsilon$ نام‌گذاری کرد~\\cite{GapJansen2007}.\n\n\\subsection{زمان‌بندی محلی: کجا باید آهسته‌تر رفت؟}\nتعریف کنید\n\\begin{equation}\n K(s)=\\max_{m>0}\\frac{M_{m0}(s)}{\\Delta_{m0}(s)^2}.\n\\end{equation}\nپیشنهاد اکتشافی برای زمان‌بندی:\n\\begin{equation}\n \\frac{dt}{ds}=\\frac{\\hbar}{\\eta}\\max\\{K(s),K_{\\mathrm{floor}}\\},\\quad\n T_{\\mathrm{loc}}=\\frac{\\hbar}{\\eta}\\int_0^1\\max\\{K,K_{\\mathrm{floor}}\\}\\,ds.\n \\label{eq:gap-local-schedule}\n\\end{equation}\n$\\eta$ هدف شاخص محلی است؛ کف مثبت از سرعت نامحدود جلوگیری می‌کند.\nمحدودیت سرعت و شتاب کنترل نیز باید اعمال شود. بیشینهٔ $K$ الزاماً نقطهٔ کمینهٔ $\\Delta$ نیست.\nزمان‌بندی خطی با همین معیار، مقیاس $\\hbar\\max K/\\eta$ دارد؛ هیچ‌یک تضمین نمی‌کند احتمال خطا دقیقاً $\\eta$ یا $\\eta^2$ باشد.\n\nکار \\lr{Roland--Cerf} نشان می‌دهد زمان‌بندی محلی در مسئلهٔ ساختاریافتهٔ جست‌وجو می‌تواند مقیاس زمان را بهبود دهد؛ این تضمین عمومی برای هر آیزینگ نیست~\\cite{GapRoland2002}.\nتغییر $s(t)$ خودِ منحنی گاف را عوض نمی‌کند؛ تغییر مسیر $H(s)$ می‌تواند آن را عوض کند.\n\n\\subsection{تقاطع اجتنابی و تقریب دو‌ترازی}\nنزدیک تقاطع اجتنابی منزوی:\n\\begin{equation}\n H_{\\mathrm{eff}}(t)=\\frac{v(t-t_*)}{2}\\sigma_z+\\frac{g}{2}\\sigma_x,\\qquad\n \\Delta(t)=\\sqrt{v^2(t-t_*)^2+g^2}.\n\\end{equation}\n$g$ گاف کمینه و $v$ سرعت تغییر اختلاف انرژی ترازهای دیاباتیک است.\nدر مسئلهٔ ایده‌آل لاندائو--زنر با جاروب خطی از زمان منفی بی‌نهایت تا مثبت بی‌نهایت:\n\\begin{equation}\n P_{\\mathrm{exc}}=\\exp[-\\pi g^2/(2\\hbar|v|)].\n\\end{equation}\nبرای مسیر محدود، چند تقاطع یا محیط اتلافی، این رابطه تنها تقریب است~\\cite{AlbashLidar2018}.\nکاهش گاف به سرعت کمتر نیاز دارد، اما پهنای ناحیهٔ حساس و شکل جاروب نیز اهمیت دارند.\n\n\\section{محاسبهٔ قابل‌بازتولید گاف در مثال دو اسپین}\n\\label{sec:gap-numerical}\n\\subsection{کاهش ماتریس با تقارن}\nهمان $h_x=J=1$ و $h_z=1/4$ را نگه می‌داریم. تقارن تعویض اسپین‌ها باعث می‌شود\n$|a\\rangle=(|01\\rangle-|10\\rangle)/\\sqrt2$ مستقل باشد، با $E_a=s$.\nدر پایهٔ متقارن $\\{|00\\rangle,(|01\\rangle+|10\\rangle)/\\sqrt2,|11\\rangle\\}$:\n\\begin{equation}\n H_{\\mathrm{sym}}(s)=\n \\begin{pmatrix}\n -3s/2&-\\sqrt2(1-s)&0\\\\\n -\\sqrt2(1-s)&s&-\\sqrt2(1-s)\\\\\n 0&-\\sqrt2(1-s)&-s/2\n \\end{pmatrix}.\n \\label{eq:gap-symmetric-matrix}\n\\end{equation}\nبا $a=-3s/2$, $b=s$, $c=-s/2$ و $w=-\\sqrt2(1-s)$، سه ریشه از\n\\begin{equation}\n (a-E)(b-E)(c-E)-w^2[(a-E)+(c-E)]=0\n\\end{equation}\nبه دست می‌آیند. ریشه‌ها را با $E_a=s$ ادغام و مرتب می‌کنیم. حل تحلیلی درجهٔ سه ممکن است، ولی حل عددی هرمیتی خواناتر و پایدارتر است. قطری‌سازی دقیق یعنی بدون آنزات یا قطع فضای این مدل؛ خطای ممیز شناور همچنان وجود دارد.\n\n\\begin{table}[htbp]\n \\centering\\small\n \\caption{قطری‌سازی دو اسپین در واحد $J=1$؛ اعداد گرد شده‌اند.}\n \\label{tab:gap-two-spin}\n \\begin{tabular}{@{}rrrr@{}}\n \\toprule $s$&$E_0$&$E_1$&$\\Delta$\\\\ \\midrule\n 0&$-2.000000$&$0.000000$&$2.000000$\\\\\n 0.25&$-1.527822$&$-0.246554$&$1.281267$\\\\\n 0.50&$-1.184807$&$-0.443966$&$0.740841$\\\\\n 0.6213&$-1.135507$&$-0.476646$&$0.658861$\\\\\n 0.75&$-1.194744$&$-0.464081$&$0.730663$\\\\\n 1&$-1.500000$&$-0.500000$&$1.000000$\\\\ \\bottomrule\n \\end{tabular}\n\\end{table}\nدر نزدیکی کمینه، علاوه بر $\\Delta_{\\min}\\simeq0.658861$:\n\\begin{equation}\n M_{10}\\simeq1.17436,\\qquad M_{10}/\\Delta_{10}^2\\simeq2.705.\n\\end{equation}\nعنصر ماتریسی گذار به حالت پادمتقارن در دقت عددی صفر است.\nجایگزینی $M_{10}$ با $\\|H'\\|=2.36961$ برآورد محافظه‌کارانه‌تری می‌دهد.\n\n\\begin{figure}[htbp]\n \\centering\\input{figures/gap_spectrum.tex}\n \\caption{طیف و گاف محاسبه‌شدهٔ دو اسپین برای $h_z=1/4$؛ خط عمودی محل کمینه است. این شکل طرحواره نیست.}\n \\label{fig:gap-computed-spectrum}\n\\end{figure}\n\n\\subsection{کمینه‌سازی روی مسیر و خطای شبکه}\nتمام بازه و دو انتها را بررسی و اطراف همهٔ کمینه‌های محتمل شبکه را ریز کنید.\nکمینهٔ شبکه کران بالای کمینهٔ پیوسته است و ممکن است گلوگاهی باریک را از دست بدهد.\nاگر $\\|H'(s)\\|\\leq L_H$، نامساوی ویل می‌دهد:\n\\begin{equation}\n |\\Delta(s)-\\Delta(s')|\\leq2L_H|s-s'|.\n\\end{equation}\nبرای شبکهٔ شامل دو انتها با بیشینهٔ فاصلهٔ $h$:\n\\begin{equation}\n \\max(0,\\Delta_{\\mathrm{grid}}-L_Hh)\\leq\\Delta_{\\min}\\leq\\Delta_{\\mathrm{grid}}.\n \\label{eq:gap-grid-bound}\n\\end{equation}\nبا خطای حداکثر $\\epsilon_g$ در هر گاف نمونه، از کران پایین $\\epsilon_g$ کم و به بالا اضافه می‌شود.\nبرای کمینهٔ هموار داخلی، هلمان--فاینمن می‌دهد:\n\\begin{equation}\n \\Delta'(s)=\\langle1|H'|1\\rangle-\\langle0|H'|0\\rangle.\n\\end{equation}\nریشهٔ مشتق فقط نامزد کمینه است؛ نقاط مرزی هم باید مقایسه شوند. در تبهگنی، بخش‌های تقارنی را جدا دنبال کنید.\n\n\\subsection{آزمون مستقیم زمان‌بندی}\nشرودینگر را برای چند $T$ حل می‌کنیم. انتشار هر ریزگام با نماییِ هامیلتونیِ نقطهٔ میانی انجام و با نصف‌کردن گام، همگرایی بررسی می‌شود. قطعات پائولی در این محاسبه تروتر نشده‌اند.\n\\begin{equation}\n P_{\\mathrm{succ}}(T)=|\\langle00|\\Psi(T)\\rangle|^2.\n\\end{equation}\nشکل~\\ref{fig:gap-schedule-test} جاروب خطی و زمان‌بندی مبتنی بر\n$\\max\\{K,0.05\\max K\\}$ را در زمان کل برابر مقایسه می‌کند.\nزمان‌بندی محلی در هر $T$ الزاماً بهتر نیست؛ تداخل گذارها می‌تواند موفقیت را نوسانی کند.\nعدد مرتبه‌ای $T\\sim500$ در مثال قبلی، کمترین زمان موفقیت نیست.\n\\begin{figure}[htbp]\n \\centering\\input{figures/gap_schedule.tex}\n \\caption{چپ: $s$ بر حسب زمان نرمال‌شده. راست: احتمال شکستِ دو زمان‌بندی در زمان کل برابر. مدل بسته و بی‌نویز است.}\n \\label{fig:gap-schedule-test}\n\\end{figure}\n\n\\subsection{گاف صفر، ولی گذار ممنوع}\nبرای $h_z=0$ تقارن $\\Pi=X_1X_2$ برقرار است و $|++\\rangle$ در بخش زوج قرار دارد.\nبا $a=1-s,b=s$، انرژی‌ها\n$\\{-\\sqrt{b^2+4a^2},-b,b,\\sqrt{b^2+4a^2}\\}$ هستند.\nگاف کل $\\sqrt{b^2+4a^2}-b$ در انتها صفر، اما گاف بخش زوج\n$2\\sqrt{b^2+4a^2}$ مثبت است.\nهدف زوج $(|00\\rangle+|11\\rangle)/\\sqrt2$ است، نه حالت یکتای $|00\\rangle$.\nاگر هدف مشخصاً $|00\\rangle$ باشد باید تقارن شکسته شود؛ مسئله و گاف مرتبط تغییر می‌کند.\n\n\\section{روش‌های محاسبهٔ گاف: انتخاب بر اساس ساختار}\n\\label{sec:gap-methods}\n\\subsection{قطری‌سازی، لانچوس و شبکهٔ تانسوری}\nبرای $n$ کیوبیت، $D=2^n$ است. ماتریس متراکم حافظهٔ $O(D^2)$ و قطری‌سازی کامل زمان نوعی $O(D^3)$ می‌خواهد.\nبرای $H=\\sum_{\\ell=1}^m c_\\ell P_\\ell$، ضرب $Hv$ را می‌توان بدون ساخت ماتریس با هزینهٔ نوعی $O(mD)$ انجام داد.\nدر لانچوس، زیرفضای\n\\begin{equation}\n {\\cal K}_k(H,v)=\\mathrm{span}\\{v,Hv,\\ldots,H^{k-1}v\\}\n\\end{equation}\nاز یک بردار شروع ساخته می‌شود. بازگشت\n$Hv_j=\\beta_jv_{j-1}+\\alpha_jv_j+\\beta_{j+1}v_{j+1}$\nماتریس سه‌قطری ایجاد می‌کند؛ کوچک‌ترین مقادیر ریتز تقریب ترازهای پایین‌اند.\nچند بردار شروع، بازمتعامدسازی و محاسبهٔ چند تراز کمک می‌کند یک تراز نزدیک یا بخش تقارنی جا نیفتد.\nهمگرایی به جدایی طیفی و هم‌پوشانی شروع وابسته است؛ تنکی، مشکل نماییِ بردار $D$بعدی را حذف نمی‌کند.\n\nبرای زوج تقریبی $(\\widetilde E,v)$ با $\\|v\\|=1$:\n\\begin{equation}\n r=Hv-\\widetilde Ev,\\qquad\n \\min_j|\\widetilde E-E_j|\\leq\\|r\\|.\n\\end{equation}\nباقیماندهٔ کوچک نزدیکی به یک ویژه‌مقدار را نشان می‌دهد، نه شناسایی قطعی $E_0$ یا $E_1$.\nبرای گاف گواهی‌شده، ترتیب ترازها یا کران‌های مستقل نیز لازم است.\n\nدر زنجیره‌های کم‌درهم‌تنیده، \\lr{DMRG/MPS} مرجع کلاسیک مناسبی است: پایه و حالت برانگیخته در بخش تقارنی مشخص به‌صورت وردشی محاسبه می‌شوند.\nهمگرایی نسبت به بُعد پیوند $\\chi$، طول زنجیره، تعداد جاروب و واریانس انرژی را بررسی کنید.\nنزدیک بحرانی‌شدن یا برای درهم‌تنیدگی زیاد، $\\chi$ لازم افزایش می‌یابد~\\cite{GapSchollwock2011}.\nمونت‌کارلو کوانتومی در مدل‌های بدون مشکل علامت نیز می‌تواند از افت همبستگی زمان موهومی گاف استخراج کند؛ بازسازی طیف از دادهٔ نویزی محدودیت دارد.\n\n\\subsection{گاف از همبستگی: کدام تراز دیده می‌شود؟}\nهمبستگی متصل زمان موهومی در پایهٔ واقعی، برای $O$ هرمیتی:\n\\begin{equation}\n C_O(\\tau)=\\sum_{m>0}|\\langle m|O|0\\rangle|^2e^{-\\Delta_{m0}\\tau/\\hbar}.\n\\end{equation}\nدر زمان بلند، شیب $-\\hbar\\,d\\log C_O/d\\tau$ به کمترین گاف دارای وزن غیرصفر میل می‌کند.\nدر زمان حقیقی همین فرکانس‌ها نوسانی‌اند. انتخاب $O$ مشخص می‌کند کدام بخش تقارنی دیده شود؛ نبود قله دلیل نبود تراز نیست.\nدر دمای غیرصفر، گذار از حالت‌های گرمایی نیز وارد می‌شود.\n\n\\subsection{QPE، VQD و قطری‌سازی زیرفضای کوانتومی}\nدر \\lr{QPE} با $U=\\exp[-i(H-E_{\\mathrm{ref}})\\tau/\\hbar]$، بازهٔ انرژی و زمان پایه باید رفع ابهام فاز را ممکن کنند.\nبرای دو تخمین با خطای مطلق $\\epsilon_E$:\n\\begin{equation}\n |\\widetilde\\Delta-\\Delta|\\leq2\\epsilon_E.\n\\end{equation}\nدقت نسبی $r_\\Delta$ نیازمند $\\epsilon_E\\lesssim r_\\Delta\\Delta/2$ است.\nزمان همدوس نوعی نسخهٔ استاندارد $O(\\hbar/\\epsilon_E)$ است؛ هزینهٔ ساخت تحول و آماده‌سازی دو حالت با هم‌پوشانی کافی نیز اضافه می‌شود.\nاگر هم‌پوشانی با تراز اول ناچیز باشد، تکرار QPE آن را به‌سادگی پیدا نمی‌کند.\n\n\\lr{VQE} معمولی فقط یک انرژی پایین را هدف می‌گیرد. در \\lr{VQD}، هزینهٔ\n\\begin{equation}\n {\\cal L}_k(\\theta)=\\langle H\\rangle_\\theta+\n \\sum_{j<k}\\mu_j|\\langle\\psi_j|\\psi(\\theta)\\rangle|^2\n\\end{equation}\nحالت‌های پایین‌تر را جریمه می‌کند؛ انتخاب $\\mu_j$ و خطای حالت‌های قبلی مهم است~\\cite{GapHiggott2019}.\nتفاضل دو کران بالای وردشی، کران بالا یا پایین تضمین‌شده‌ای برای گاف نیست.\n\nدر روش زیرفضایی، پایهٔ آزمایشی از تحریک‌های حالت مرجع یا تحول‌های زمانی ساخته می‌شود:\n\\begin{equation}\n A_{ij}=\\langle\\phi_i|H|\\phi_j\\rangle,\\quad\n S_{ij}=\\langle\\phi_i|\\phi_j\\rangle,\\quad Ac=ESc.\n\\end{equation}\nمقادیر بسیار کوچک $S$ نویز را تقویت می‌کنند؛ آستانه‌گذاری و همگرایی نسبت به اندازهٔ زیرفضا باید گزارش شود.\nزیرفضای خوب برای پایه الزاماً حالت برانگیختهٔ لازم را در بر ندارد.\n\n\\subsection{برآورد مستقیم از نوسان دو حالت}\nاگر $|\\psi\\rangle=c_0|0\\rangle+c_1|1\\rangle$ و $O_{01}\\ne0$ باشد:\n\\begin{equation}\n \\langle O(t)\\rangle=A+\n 2\\,\\mathrm{Re}[c_0^*c_1O_{01}e^{-i\\Delta t/\\hbar}].\n \\label{eq:gap-oscillation}\n\\end{equation}\nبرای وزن‌های برابر، دامنه $|O_{01}|$ است. برازش فرکانس، گاف را بدون تفاضل دو انرژی مطلق می‌دهد.\nیک حالت ویژهٔ تنها با $H$ ثابت برای این هدف نوسان ندارد؛ حالت‌های اضافی، سیگنال چندفرکانسی ایجاد می‌کنند.\nدر فوریهٔ ساده، طول پنجره $t_{\\max}$ تفکیک نوعی\n$\\delta E\\sim2\\pi\\hbar/t_{\\max}$ می‌دهد؛ گام نمونه‌برداری نیز باید مانع هم‌پوشانی فرکانسی شود.\nبرازش پارامتری گاهی از یک خانهٔ فوریه دقیق‌تر است، ولی به شات، دامنه، نویز و درستی مدل وابسته است.\n\n\\section{افزایش اندازه، بحرانی‌شدن و پیچیدگی}\n\\label{sec:gap-scaling}\n\\subsection{تعداد کیوبیت و واحد انرژی}\nبرای اسپین-$1/2$ هر سایت یک کیوبیت است؛ برای اتم چندترازی یا مد بوزونیِ بریده‌شده چنین نیست.\nبا بُعد محلی $d_{\\mathrm{loc}}$، $D=d_{\\mathrm{loc}}^N$ است.\nهنگام مقایسهٔ $\\Delta_{\\min}(n)$، انرژی هر برهم‌کنش محلی را ثابت نگه دارید.\nجایگزینی $H$ با $cH$ گاف‌ها را $c$ برابر و مقیاس زمان فیزیکی را $1/c$ می‌کند؛ این افزایش توان کنترل است، نه بهبود رایگان پیچیدگی.\nتقسیم هامیلتونی گسترده بر $n$ هم ممکن است گاف ثابت را ظاهراً $1/n$ کند.\n\n\\subsection{سه رفتار و یک مثال حل‌پذیر}\nاسپین‌های مستقل $H=-h\\sum_iX_i$ برای هر $n$ گاف $2h$ دارند.\nنزدیک نقطهٔ بحرانی پیوسته، رفتار نوعی با طول خطی $L$:\n\\begin{equation}\n \\Delta(L,g)\\simeq JL^{-z}{\\cal F}((g-g_c)L^{1/\\nu}),\\qquad n=L^d.\n\\end{equation}\n$z$ نمای دینامیکی و $\\nu$ نمای طول همبستگی است؛ این فرض مقیاس‌بندی بحرانی با تصحیح اندازهٔ محدود است، نه قانون همهٔ مدل‌ها.\nدر برخی تقاطع‌های تونلی و گذارهای مرتبهٔ اول گاف نمایی کوچک می‌شود.\n\nبرای زنجیرهٔ باز یکنواخت\n\\begin{equation}\n H=-J\\sum_{i=1}^{n-1}Z_iZ_{i+1}-h\\sum_{i=1}^nX_i,\\qquad g=h/J,\n\\end{equation}\nتبدیل به فرمیون آزاد، حل با ماتریسی از اندازهٔ $n$ را ممکن می‌کند.\nاگر $B$ قطر $h$ و قطر پایین $-J$ داشته باشد، انرژی تحریک‌های مثبت $2\\sigma_j(B)$ هستند؛ کوچک‌ترین آن‌ها گاف کل است.\nدر $g=1$:\n\\begin{equation}\n \\Delta_n=4J\\sin\\!\\left(\\frac{\\pi}{4n+2}\\right)\\sim\\frac{\\pi J}{n}.\n \\label{eq:gap-open-chain}\n\\end{equation}\nاین نتیجه برای همین شرایط مرزی و قرارداد پائولی است.\nدر فاز مرتبِ زنجیرهٔ باز، شکافت دو حالت کم‌انرژی می‌تواند نمایی کوچک شود، در حالی‌که گاف حجمی تحریک‌ها محدود بماند.\n\\begin{figure}[htbp]\n \\centering\\input{figures/gap_scaling.tex}\n \\caption{گاف زنجیرهٔ باز از محاسبهٔ مقادیر تکین برای $g=1.5,1,0.5$. منحنی فاز مرتب شکافت کل کم‌انرژی را نشان می‌دهد، نه گاف حجمی. قدرت محلی $J=1$ ثابت است.}\n \\label{fig:gap-size-scaling}\n\\end{figure}\n\n\\subsection{هزینهٔ یافتن گاف در برابر هزینهٔ اجرا}\nاگر $\\|H'\\|$ با $n$ رشد کند، تخمین زمان باید این رشد را هم لحاظ کند.\nگاف چندجمله‌ای همراه مسیر هموارِ قابل‌ساخت و مشتقات کنترل‌شده با اجرای کارآمد سازگار است؛ اثبات کارایی به هزینهٔ تمام اجزا نیاز دارد.\n\nدر بدترین حالت، تعیین انرژی پایهٔ هامیلتونی محلی با دقت وعده‌داده‌شدهٔ معکوس چندجمله‌ای، \\lr{QMA}-کامل است؛ \\lr{QMA} همتای کوانتومی بررسی گواه محاسباتی است.\nاین نتیجه اثبات سختی هر نمونهٔ فیزیکی یا طبقه‌بندی یکسان همهٔ مسائل گاف نیست~\\cite{GapGharibian2015}.\nحل‌ناپذیری تصمیم‌گیری گاف در حد ترمودینامیکی برای خانواده‌های خاص نتیجهٔ دیگری است و مانع قطری‌سازی ماتریس متناهی معلوم نمی‌شود~\\cite{GapCubitt2015}.\n\nبرازش چند اندازهٔ کوچک به نمایی یا توانی کافی نیست. دادهٔ بزرگ‌تر، تقارن، مرزها و مدل برازش جایگزین را بررسی کنید.\nدر مسائل بی‌نظم علاوه بر میانگین، توزیع $\\log\\Delta_{\\min}$ و نمونه‌های نادر اهمیت دارند.\n\n\\section{کاهش زمان و بهای آن}\n\\label{sec:gap-control}\n\\begin{enumerate}\n \\item \\textbf{زمان‌بندی و هموارکردن ابتدا/انتها.}\n سرعت را با گاف و عناصر گذار تنظیم کنید؛ هزینهٔ برآورد مسیر جدا حساب شود.\n \\item \\textbf{تغییر مسیر.}\n جملهٔ قابل‌کنترل $f(s)H_{\\mathrm{cat}}$ با $f(0)=f(1)=0$ اضافه کنید.\n کل مسیر جدید باید بررسی شود؛ بزرگ‌شدن گاف در یک نقطه کافی نیست.\n افزایش دامنه یا غیرمحلی‌شدن جمله‌ها منابع اضافی‌اند.\n \\item \\textbf{رانش جبران‌کنندهٔ گذار.}\n در قرارداد\n \\begin{equation}\n H_{\\mathrm{tot}}=H+\\dot s\\,{\\cal A}_s,\\qquad\n \\langle m|{\\cal A}_s|n\\rangle\n =i\\hbar\\frac{\\langle m|H'|n\\rangle}{E_n-E_m}\\quad(m\\ne n),\n \\end{equation}\n جملهٔ اضافی گذار ناشی از حرکت پایه را جبران می‌کند. نزدیک گاف کوچک می‌تواند بزرگ یا غیرمحلی شود.\n روش وردشی \\lr{Sels--Polkovnikov} با محدودکردن $\\mathcal{A}_s$ به عملگرهای قابل‌اجرا، تقریب عملی‌تری می‌سازد؛ بهبود وابسته به مدل و منابع کنترل است~\\cite{GapSels2017}.\n \\item \\textbf{مسیر غیرآدیاباتیک و وردشی.}\n \\lr{QAOA} یا کنترل بهینه می‌تواند عمداً در میانه حالت برانگیخته را اشغال کند.\n معیار، موفقیت در هزینهٔ کل برابر است؛ چنین پروتکلی صرفاً آزمون قضیهٔ آدیاباتیک نیست.\n\\end{enumerate}\nدر سامانهٔ باز، اجرای طولانی‌تر ممکن است ناهمدوسی را بیشتر کند.\nمقایسهٔ $k_BT_{\\mathrm{bath}}$ با گاف مفید است، اما نرخ گذار و عملگر جفت‌شدگی محیط هم مهم‌اند.\nگاف لیوویلی معادلهٔ مادر با گاف انرژی هامیلتونی یکسان نیست.\n\n\\section{مرور هدفمند منابع و روش‌های جاری}\n\\label{sec:gap-papers}\nاین مرور گزینشی بر منابع بررسی‌شده تا ۱۴ سپتامبر ۲۰۲۶ تکیه دارد؛ مرور نظام‌مند همهٔ مقالات نیست.\nچون مقالهٔ مشخصی در درخواست معرفی نشده، چند مسیر مکمل انتخاب شده‌اند.\nوضعیت پیش‌چاپ از مقالهٔ منتشرشده جدا شده است.\n\n\\paragraph{پایهٔ نظری و محاسبات کلاسیک.}\n\\lr{Jansen--Ruskai--Seiler (2007)} برای فرض‌ها و کران آدیاباتیک،\n\\lr{Roland--Cerf (2002)} برای زمان‌بندی محلی،\nو مرور \\lr{Schollwock (2011)} برای \\lr{MPS/DMRG} مراجع آغاز مناسب‌اند.\nمرور \\lr{Albash--Lidar (2018)} پیوند این مباحث با محاسبهٔ آدیاباتیک را توضیح می‌دهد~\\cite{GapJansen2007,GapRoland2002,GapSchollwock2011,AlbashLidar2018}.\n\n\\paragraph{برآورد ترکیبی گاف با پردازش سیگنال؛ مقالهٔ ۲۰۲۵.}\n\\lr{Lee, Myers, Scarola} در \\lr{Physical Review A 111, 022421}\nتحول کوانتومی، بهینه‌سازی حالت آزمایشی و پردازش کلاسیک سیگنال را ترکیب می‌کنند.\nتحلیل مقاومت به نویز برای مدل‌های مشخص انجام شده؛ این به معنای حذف همهٔ نویزها نیست.\nکاربرد برای پروژهٔ ما: بررسی قابل‌دیدن بودن قلهٔ گاف و هزینهٔ شات/عمق در امتداد مسیر، همراه آزمون حساسیت به مدل نویز~\\cite{GapLee2025}.\n\n\\paragraph{آماده‌سازی آدیاباتیک و برازش نوسان؛ پیش‌چاپ دسامبر ۲۰۲۵.}\n\\lr{Cugini et al.} در\n\\lr{Spectral Gap Estimation via Adiabatic Preparation}\nاز برهم‌نهی دو حالت و نوسان مشاهده‌پذیر استفاده می‌کنند؛ نتایجی برای آیزینگ و مدل‌های مولکولی و اجرای آیزینگ تا ۲۰ کیوبیت گزارش شده است.\nبرای انتقال ایده به پروژه، باید نشان داد دو شاخهٔ مطلوب آماده شده‌اند، مشاهده‌پذیر وزن گذار دارد و برازش چندقله‌ای لازم نیست.\nهزینهٔ آماده‌سازی را نمی‌توان هنگام ادعای کاهش هزینهٔ اندازه‌گیری گاف حذف کرد~\\cite{GapCugini2025}.\n\n\\paragraph{شمارش طیفی؛ مقالهٔ منتشرشدهٔ ۲۰۲۶.}\n\\lr{Carrera Vazquez--Sobczyk} در \\lr{Quantum 10, 2067}\nگاف مرتب‌شدهٔ ماتریس هرمیتی و نقطهٔ میانی آن را با پرسمان شمارش بررسی می‌کنند.\nدر مدل دسترسی \\lr{QRAM}، هزینه شامل عامل\n$D^2/(\\epsilon^2\\Delta_k^2)$ و عوامل چندلگاریتمی است.\nبا $D=2^n$ این عامل هنوز نمایی در تعداد کیوبیت سامانه است؛ ثبات لگاریتمی را نباید با زمان چندجمله‌ای در $n$ یکی گرفت.\nسهم پژوهشی آن الگوریتم و تحلیل در مدل دسترسی مشخص است~\\cite{GapCarrera2026}.\n\n\\paragraph{زیرفضای نمونه‌برداری‌شده؛ مسیر مرتبط، نه تضمین آمادهٔ گاف.}\n\\lr{Yu et al. (2025)} در \\lr{SKQD} نمونه‌برداری کوانتومی از حالت‌های کریلوف را با قطری‌سازی کلاسیک ترکیب می‌کنند.\nتضمین همگرایی پایه فرض‌هایی از جمله ساختار حالت و پراکندگی آن در پایهٔ نمونه‌برداری دارد.\nتعمیم به گاف مستلزم حضور و کنترل خطای حالت برانگیخته نیز هست؛ این یک فرصت پژوهشی است، نه نتیجهٔ خودکارِ روش پایه~\\cite{GapYu2025}.\n\\lr{VQD} مرجع دیگری برای هدف‌گیری ترازهای برانگیخته است~\\cite{GapHiggott2019}.\n\n\\section{جریان کاری و مسیرهای پیشنهادی پژوهش}\n\\label{sec:gap-projects}\n\\begin{figure}[htbp]\n \\centering\\input{figures/gap_workflow.tex}\n \\caption{گاف، عدم‌قطعیت و هزینهٔ یافتن آن، همگی ورودی طراحی زمان‌بندی‌اند؛ حلقه با آزمون دینامیکی بسته می‌شود.}\n \\label{fig:gap-workflow}\n\\end{figure}\nبرای هر نتیجه ثبت کنید: مدل و واحد انرژی، اندازه و مرزها، تعریف گاف و بخش تقارنی، روش، خطای ترازها، دقت شبکهٔ $s$، محل کمینه، عناصر گذار، زمان کل، احتمال موفقیت و منابع کلاسیک/کوانتومی.\n\nسه موضوع قابل‌آغاز با فرضیهٔ قابل‌آزمون:\n\\begin{enumerate}\n \\item \\textbf{زمان‌بندی مقاوم به خطای گاف در زنجیرهٔ آیزینگ.}\n مرجع دقیق برای اندازه‌های کوچک؛ سپس برآورد نویزی و مقایسهٔ جاروب خطی، محلی و محافظه‌کارانه در زمان برابر.\n معیار: احتمال موفقیت، بدترین افت تحت خطای گاف و هزینهٔ نمونه‌برداری.\n نوآوری باید در تحمل عدم‌قطعیت یا کاهش هزینه باشد، نه صرف بازتولید زمان‌بندی محلی.\n \\item \\textbf{طیف‌سنجی با انتخاب مشاهده‌پذیر بر اساس تقارن.}\n چند عملگر با قواعد انتخاب متفاوت را مقایسه کنید و بسنجید چه وقت اولین قله، گاف هدف را پنهان می‌کند.\n مرجع قطری‌سازی، برازش چندفرکانسی و نویز خوانش لازم‌اند؛ مقالات \\lr{Lee} و \\lr{Cugini} نقطهٔ شروع‌اند.\n \\item \\textbf{زیرفضای مشترک پایه و برانگیخته.}\n در \\lr{VQD/Krylov} خطای دو تراز و اندازهٔ زیرفضا را کنترل و با مرجع مقایسه کنید.\n سؤال: آیا در هزینهٔ یکسان، هدف‌گیری هم‌زمان دو حالت از تفاضل دو بهینه‌سازی مستقل قابل‌اعتمادتر است؟\n\\end{enumerate}\nاین‌ها پیشنهاد مسئله‌اند، نه ادعای نوآوری اثبات‌شده. انتخاب نهایی پس از تعیین مدل، سکو، دامنهٔ اندازه‌ها و بررسی دقیق‌تر پیشینه انجام می‌شود.\nفایل \\lr{figures/gap_research_compute.py} محاسبات و نمودارهای این بخش را بازتولید می‌کند؛ داده‌ها و آزمون همگرایی کنار شکل‌ها ذخیره می‌شوند.\nدو اسپین برای فهم و راستی‌آزمایی است و به‌تنهایی شاهد مزیت کوانتومی نیست.\n% END GAP RESEARCH EXPANSION\n"
