bib="\n@article{GapJansen2007,\n author={Jansen, Sabine and Ruskai, Mary-Beth and Seiler, Ruedi},\n title={Bounds for the adiabatic approximation with applications to quantum computation},\n journal={Journal of Mathematical Physics}, volume={48}, pages={102111}, year={2007},\n doi={10.1063/1.2798382}, url={https://arxiv.org/abs/quant-ph/0603175}}\n@article{GapRoland2002,\n author={Roland, Jeremie and Cerf, Nicolas J.},\n title={Quantum Search by Local Adiabatic Evolution},\n journal={Physical Review A}, volume={65}, pages={042308}, year={2002},\n doi={10.1103/PhysRevA.65.042308}, url={https://arxiv.org/abs/quant-ph/0107015}}\n@article{GapSchollwock2011,\n author={Schollw{\\\"o}ck, Ulrich},\n title={The density-matrix renormalization group in the age of matrix product states},\n journal={Annals of Physics}, volume={326}, pages={96--192}, year={2011},\n doi={10.1016/j.aop.2010.09.012}, url={https://arxiv.org/abs/1008.3477}}\n@article{GapHiggott2019,\n author={Higgott, Oscar and Wang, Daochen and Brierley, Stephen},\n title={Variational Quantum Computation of Excited States},\n journal={Quantum}, volume={3}, pages={156}, year={2019},\n doi={10.22331/q-2019-07-01-156}, url={https://arxiv.org/abs/1805.08138}}\n@article{GapSels2017,\n author={Sels, Dries and Polkovnikov, Anatoli},\n title={Minimizing irreversible losses in quantum systems by local counterdiabatic driving},\n journal={Proceedings of the National Academy of Sciences}, volume={114}, pages={E3909--E3916}, year={2017},\n doi={10.1073/pnas.1619826114}, url={https://arxiv.org/abs/1607.05687}}\n@article{GapCubitt2015,\n author={Cubitt, Toby S. and Perez-Garcia, David and Wolf, Michael M.},\n title={Undecidability of the spectral gap},\n journal={Nature}, volume={528}, pages={207--211}, year={2015},\n doi={10.1038/nature16059}, url={https://arxiv.org/abs/1502.04135}}\n@article{GapGharibian2015,\n author={Gharibian, Sevag and Huang, Yichen and Landau, Zeph and Shin, Seung Woo},\n title={Quantum Hamiltonian Complexity},\n journal={Foundations and Trends in Theoretical Computer Science},\n volume={10}, pages={159--282}, year={2015}, doi={10.1561/0400000066},\n url={https://arxiv.org/abs/1401.3916}}\n@article{GapLee2025,\n author={Lee, Woo-Ram and Myers, Nathan M. and Scarola, V. V.},\n title={Noise-resilient and resource-efficient hybrid algorithm for robust quantum gap estimation},\n journal={Physical Review A}, volume={111}, pages={022421}, year={2025},\n doi={10.1103/PhysRevA.111.022421}}\n@misc{GapCugini2025,\n author={Cugini, Davide and Ghisoni, Francesco and Morgillo, Angela Rosy and Scala, Francesco},\n title={Spectral Gap Estimation via Adiabatic Preparation},\n year={2025}, eprint={2512.19288}, archivePrefix={arXiv},\n note={Preprint}, url={https://arxiv.org/abs/2512.19288}}\n@article{GapCarrera2026,\n author={Carrera Vazquez, Almudena and Sobczyk, Aleksandros},\n title={Spectral Gaps with Quantum Counting Queries and Oblivious State Preparation},\n journal={Quantum}, volume={10}, pages={2067}, year={2026},\n doi={10.22331/q-2026-04-15-2067}, url={https://arxiv.org/abs/2508.21002}}\n@misc{GapYu2025,\n author={Yu, Jeffery and Robledo Moreno, Javier and Iosue, Joseph T. and Bertels, Luke and Claudino, Daniel and others},\n title={Quantum-Centric Algorithm for Sample-Based Krylov Diagonalization},\n year={2025}, eprint={2501.09702}, archivePrefix={arXiv}, note={Preprint, version 3},\n url={https://arxiv.org/abs/2501.09702}}\n"
